cd /workspace/nox/web/site
python3 - <<'P'
import re,time
t=str(int(time.time()))
s=open('chat.html',encoding='utf-8').read()
open('chat.html.bak_s1_rq','w',encoding='utf-8').write(s)
if 'nox-chat-rq.js' not in s:
    s=s.replace('</body>','<link rel="stylesheet" href="./nox-chat-rq.css?v='+t+'">\n<script src="./nox-ghost.js?v='+t+'" defer></script>\n<script src="./nox-chat-rq.js?v='+t+'" defer></script>\n</body>',1)
open('chat.html','w',encoding='utf-8').write(s)
for fn in ['system.html','index.html','chat.html']:
    x=open(fn,encoding='utf-8').read()
    x=re.sub(r'nox-hud-s1\.(js|css)\?v=[0-9]*',lambda m:'nox-hud-s1.'+m.group(1)+'?v='+t,x); open(fn,'w',encoding='utf-8').write(x)
try:
